using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared configuration for evaluation runs including telemetry, quality scorers,
/// and chat client setup.
/// </summary>
internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string ModelId =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var credential = new Azure.AzureKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "");

        return new Azure.AI.Inference.ChatCompletionsClient(new Uri(Endpoint), credential)
            .AsIChatClient(ModelId);
    }

    public static TracerProvider ConfigureTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Evals")
            .AddOtlpExporter(opts =>
            {
                opts.Endpoint = new Uri(
                    Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT")
                    ?? "http://localhost:4317");
            })
            .Build()!;
    }

    public static IList<IEvaluator> QualityEvaluators(IChatClient judge) =>
    [
        new RelevanceEvaluator(judge),
        new CoherenceEvaluator(judge),
        new FluencyEvaluator(judge),
        new GroundednessEvaluator(judge),
    ];

    public static ReportingConfiguration CreateReportingConfig(string runName) =>
        new(storageRootPath: Path.Combine("eval-results", runName));
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI calls produce the expected OpenTelemetry spans.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private TracerProvider _telemetry = null!;

    [TestInitialize]
    public void Setup()
    {
        _telemetry = EvalConfig.ConfigureTelemetry();
    }

    [TestCleanup]
    public void Cleanup()
    {
        _telemetry.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTrace()
    {
        var client = EvalConfig.CreateChatClient();

        var response = await client.GetResponseAsync("Hello, how can you help me?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one message in response.");

        // Telemetry spans are flushed on dispose; verify no exception during flush.
        _telemetry.ForceFlush();
    }

    [TestMethod]
    public async Task StreamingCompletion_EmitsTrace()
    {
        var client = EvalConfig.CreateChatClient();

        var tokens = new List<string>();
        await foreach (var update in client.GetStreamingResponseAsync("Give a brief greeting."))
        {
            if (update.Text is not null)
                tokens.Add(update.Text);
        }

        Assert.IsTrue(tokens.Count > 0, "Expected streaming tokens.");
        _telemetry.ForceFlush();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates response quality using AI judges for relevance,
/// coherence, fluency, and groundedness.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IChatClient _client = null!;
    private static IChatClient _judge = null!;
    private static ReportingConfiguration _reporting = null!;

    [ClassInitialize]
    public static void ClassInit(TestContext _)
    {
        _client = EvalConfig.CreateChatClient();
        _judge = EvalConfig.CreateChatClient();
        _reporting = EvalConfig.CreateReportingConfig("quality");
    }

    [TestMethod]
    public async Task CoachingResponse_MeetsQualityBar()
    {
        var prompt = "I'm struggling with time management at work. Can you help?";
        var response = await _client.GetResponseAsync(prompt);
        var responseText = response.Text ?? "";

        var evaluators = EvalConfig.QualityEvaluators(_judge);

        var context = new EvaluationContext();
        context.Set("prompt", prompt);
        context.Set("response", responseText);

        var results = new List<EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(
                [new ChatMessage(ChatRole.User, prompt)],
                new ChatResponse([new ChatMessage(ChatRole.Assistant, responseText)]),
                context);
            results.Add(result);
        }

        foreach (var result in results)
        {
            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.IsTrue(
                        numericValue.Value >= 3.0,
                        $"Metric '{metric.Key}' scored {numericValue.Value}, expected >= 3.0");
                }
            }
        }
    }

    [TestMethod]
    public async Task FollowUpQuestion_IsRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to improve my public speaking."),
            new(ChatRole.Assistant, "That's a great goal! What specific situations make you most nervous?"),
            new(ChatRole.User, "Mostly large meetings at work."),
        };

        var response = await _client.GetResponseAsync(messages);
        var responseText = response.Text ?? "";

        var evaluators = EvalConfig.QualityEvaluators(_judge);

        var context = new EvaluationContext();
        context.Set("prompt", "Mostly large meetings at work.");
        context.Set("response", responseText);

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(
                messages,
                new ChatResponse([new ChatMessage(ChatRole.Assistant, responseText)]),
                context);

            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.IsTrue(
                        numericValue.Value >= 3.0,
                        $"Metric '{metric.Key}' scored {numericValue.Value}, expected >= 3.0");
                }
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and
/// compares quality metrics side-by-side. Use to validate model upgrades or
/// prompt changes don't regress quality.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string[] TestPrompts =
    [
        "How can I stay focused while working from home?",
        "What are some strategies for dealing with imposter syndrome?",
        "Help me prepare for a difficult conversation with my manager.",
    ];

    [TestMethod]
    public async Task CompareBaseline_VsCandidate()
    {
        var baselineModelId = Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini";
        var candidateModelId = Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o-mini";

        var judge = EvalConfig.CreateChatClient();
        var evaluators = EvalConfig.QualityEvaluators(judge);

        var baselineScores = await RunScenarios(baselineModelId, evaluators);
        var candidateScores = await RunScenarios(candidateModelId, evaluators);

        // Report comparison
        Console.WriteLine($"{"Metric",-20} {"Baseline",-12} {"Candidate",-12} {"Delta",-10}");
        Console.WriteLine(new string('-', 54));

        foreach (var metric in baselineScores.Keys)
        {
            var baselineAvg = baselineScores[metric] / TestPrompts.Length;
            var candidateAvg = candidateScores[metric] / TestPrompts.Length;
            var delta = candidateAvg - baselineAvg;
            var indicator = delta >= 0 ? "✓" : "✗";

            Console.WriteLine($"{metric,-20} {baselineAvg,-12:F2} {candidateAvg,-12:F2} {delta,-8:+0.00;-0.00} {indicator}");
        }

        // Assert candidate is not significantly worse than baseline
        foreach (var metric in baselineScores.Keys)
        {
            var baselineAvg = baselineScores[metric] / TestPrompts.Length;
            var candidateAvg = candidateScores[metric] / TestPrompts.Length;

            Assert.IsTrue(
                candidateAvg >= baselineAvg - 0.5,
                $"Candidate regressed on '{metric}': baseline={baselineAvg:F2}, candidate={candidateAvg:F2}");
        }
    }

    private static async Task<Dictionary<string, double>> RunScenarios(
        string modelId, IList<IEvaluator> evaluators)
    {
        var scores = new Dictionary<string, double>();
        var client = EvalConfig.CreateChatClient();

        foreach (var prompt in TestPrompts)
        {
            var response = await client.GetResponseAsync(prompt);
            var responseText = response.Text ?? "";

            var context = new EvaluationContext();
            context.Set("prompt", prompt);
            context.Set("response", responseText);

            foreach (var evaluator in evaluators)
            {
                var result = await evaluator.EvaluateAsync(
                    [new ChatMessage(ChatRole.User, prompt)],
                    new ChatResponse([new ChatMessage(ChatRole.Assistant, responseText)]),
                    context);

                foreach (var metric in result.Metrics)
                {
                    if (metric.Value is NumericMetricValue numericValue)
                    {
                        if (!scores.ContainsKey(metric.Key))
                            scores[metric.Key] = 0;
                        scores[metric.Key] += numericValue.Value;
                    }
                }
            }
        }

        return scores;
    }
}

