using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared configuration for evaluation runs including telemetry, quality scorers,
/// and chat client setup.
/// </summary>
internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string ModelId =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var credential = new Azure.AzureKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "");

        return new Azure.AI.Inference.ChatCompletionsClient(new Uri(Endpoint), credential)
            .AsIChatClient(ModelId);
    }

    public static TracerProvider ConfigureTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Evals")
            .AddOtlpExporter(opts =>
            {
                opts.Endpoint = new Uri(
                    Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT")
                    ?? "http://localhost:4317");
            })
            .Build()!;
    }

    public static IList<IEvaluator> QualityEvaluators(IChatClient judge) =>
    [
        new RelevanceEvaluator(judge),
        new CoherenceEvaluator(judge),
        new FluencyEvaluator(judge),
        new GroundednessEvaluator(judge),
    ];

    public static ReportingConfiguration CreateReportingConfig(string runName) =>
        new(storageRootPath: Path.Combine("eval-results", runName));
}

