using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI calls produce the expected OpenTelemetry spans.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private TracerProvider _telemetry = null!;

    [TestInitialize]
    public void Setup()
    {
        _telemetry = EvalConfig.ConfigureTelemetry();
    }

    [TestCleanup]
    public void Cleanup()
    {
        _telemetry.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTrace()
    {
        var client = EvalConfig.CreateChatClient();

        var response = await client.GetResponseAsync("Hello, how can you help me?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0, "Expected at least one message in response.");

        // Telemetry spans are flushed on dispose; verify no exception during flush.
        _telemetry.ForceFlush();
    }

    [TestMethod]
    public async Task StreamingCompletion_EmitsTrace()
    {
        var client = EvalConfig.CreateChatClient();

        var tokens = new List<string>();
        await foreach (var update in client.GetStreamingResponseAsync("Give a brief greeting."))
        {
            if (update.Text is not null)
                tokens.Add(update.Text);
        }

        Assert.IsTrue(tokens.Count > 0, "Expected streaming tokens.");
        _telemetry.ForceFlush();
    }
}

